        assert values[2*n] == values[n] ** 2 - 2

from typing import List, Tuple

def conic_walk(t: int, steps: int) -> List[Tuple[int, int]]:
    x, y = 2, t
    points: List[Tuple[int, int]] = []
    for _ in range(steps + 1):
        points.append((x, y))
        assert x*x - t*x*y + y*y == 4 - t*t
        x, y = y, t*y - x
    return points

if __name__ == "__main__":
    for point in conic_walk(4, 10):
        print(point)

